:where([data-moru-registry]) .ui-context-menu-trigger {
  box-sizing: border-box;
  min-width: 0;
  font-family: var(--ui-font-family, inherit);
  font-size: var(--ui-type-label-size, 13px);
  font-weight: var(--ui-type-label-weight, 550);
  line-height: var(--ui-type-label-line-height, 1.5);
  letter-spacing: var(--ui-type-label-letter-spacing, -0.015em);
  color: var(--ui-text, #171717);
  overflow-wrap: anywhere;
  --ui-navigation-height: var(--ui-control-height-md, 40px);
  --ui-navigation-padding: var(--ui-control-padding-x-md, 14px);
  --ui-navigation-icon: var(--ui-icon-size-md, 16px);
  --ui-navigation-close-size: var(--ui-control-height-sm, 32px);
}
:where([data-moru-registry]) [data-size='sm'].ui-context-menu-trigger {
  --ui-navigation-height: var(--ui-control-height-sm, 32px);
  --ui-navigation-padding: var(--ui-control-padding-x-sm, 10px);
  --ui-navigation-icon: var(--ui-icon-size-sm, 14px);
  font-size: var(--ui-type-caption-size, 12px);
}
:where([data-moru-registry]) [data-size='lg'].ui-context-menu-trigger {
  --ui-navigation-height: var(--ui-control-height-lg, 48px);
  --ui-navigation-padding: var(--ui-control-padding-x-lg, 18px);
  --ui-navigation-icon: var(--ui-icon-size-lg, 18px);
}
:where([data-moru-registry]) .ui-context-menu-trigger {
  display: grid;
  place-items: center;
  width: 100%;
  min-height: calc(var(--ui-navigation-height) * 2.5);
  gap: var(--ui-field-gap, 8px);
  padding: var(--ui-navigation-padding);
  border: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
  border-radius: calc(var(--ui-radius, 6px) + 4px);
  text-align: center;
  cursor: context-menu;
  background: var(--ui-control-hover-bg, #f3f3f1);
}
:where([data-moru-registry]) .ui-context-menu-trigger[aria-disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useI18n } from './_lib/i18n'
import { useEffect, useRef, useState, type ReactNode } from 'react'
import { ContextMenu as BaseContextMenu } from '@base-ui/react/context-menu'
import { cn } from './_lib/cn'
import { NavigationMenuActions, type NavigationAction } from './navigation-menu-items'
import { useThemePortalContainer } from './theme-scope'
import { OverlayPortal } from './overlay-portal'
import './navigation-shared.css'
import './context-menu.css'

export type ContextMenuItem = NavigationAction
export interface ContextMenuProps {
  children: ReactNode
  items: ContextMenuItem[]
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  disabled?: boolean
  size?: 'sm' | 'md' | 'lg'
  className?: string
  'aria-label'?: string
}
export function ContextMenu({
  children,
  items,
  open,
  defaultOpen = false,
  onOpenChange,
  disabled,
  size = 'md',
  className,
  'aria-label': labelProp,
}: ContextMenuProps) {
  const { t } = useI18n()
  const label = labelProp ?? t('컨텍스트 메뉴 영역')

  const portalContainer = useThemePortalContainer()
  const triggerRef = useRef<HTMLDivElement>(null)
  const [localOpen, setLocalOpen] = useState(defaultOpen)
  const [keyboardAnchor, setKeyboardAnchor] = useState<HTMLElement | null>(null)
  const shown = !disabled && (open ?? localOpen)
  useEffect(() => {
    if (disabled && open === undefined) setLocalOpen(false)
  }, [disabled, open])
  function changeOpen(next: boolean) {
    if (next && disabled) return
    if (open === undefined) setLocalOpen(next)
    onOpenChange?.(next)
  }
  return (
    <BaseContextMenu.Root open={shown} onOpenChange={changeOpen} disabled={disabled}>
      <BaseContextMenu.Trigger
        ref={triggerRef}
        className={cn('ui-context-menu-trigger', className)}
        data-size={size}
        tabIndex={disabled ? -1 : 0}
        aria-disabled={disabled || undefined}
        aria-label={label}
        aria-haspopup="menu"
        aria-expanded={shown}
        onContextMenu={() => setKeyboardAnchor(null)}
        onKeyDown={(event) => {
          if (disabled || !(event.key === 'ContextMenu' || (event.shiftKey && event.key === 'F10')))
            return
          event.preventDefault()
          setKeyboardAnchor(event.currentTarget)
          changeOpen(true)
        }}
      >
        {children}
      </BaseContextMenu.Trigger>
      <OverlayPortal portal={BaseContextMenu.Portal} kind="menu" container={portalContainer}>
        <BaseContextMenu.Positioner
          positionMethod="fixed"
          className="ui-navigation-positioner"
          anchor={keyboardAnchor ?? undefined}
          align="start"
          sideOffset={4}
          collisionPadding={12}
        >
          <BaseContextMenu.Popup
            className="ui-navigation-popup"
            data-size={size}
            aria-label={label}
            finalFocus={triggerRef}
          >
            <NavigationMenuActions items={items} size={size} />
          </BaseContextMenu.Popup>
        </BaseContextMenu.Positioner>
      </OverlayPortal>
    </BaseContextMenu.Root>
  )
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import type { ReactNode } from 'react'
import { Menu as BaseMenu } from '@base-ui/react/menu'
import { ChevronRight } from 'lucide-react'
import { useThemePortalContainer } from './theme-scope'
import { OverlayPortal } from './overlay-portal'

export interface NavigationAction {
  id: string
  label: string
  icon?: ReactNode
  shortcut?: string
  disabled?: boolean
  destructive?: boolean
  onSelect?: () => void
  children?: NavigationAction[]
}

export function NavigationMenuActions({
  items,
  size,
}: {
  items: NavigationAction[]
  size: 'sm' | 'md' | 'lg'
}) {
  const portalContainer = useThemePortalContainer()
  return items.map((item) =>
    item.children?.length ? (
      <BaseMenu.SubmenuRoot key={item.id}>
        <BaseMenu.SubmenuTrigger
          className="ui-navigation-action"
          disabled={item.disabled}
          label={item.label}
        >
          {item.icon ? (
            <span className="ui-navigation-action-icon" aria-hidden="true">
              {item.icon}
            </span>
          ) : null}
          <span>{item.label}</span>
          <ChevronRight className="ui-navigation-action-end" size={14} aria-hidden="true" />
        </BaseMenu.SubmenuTrigger>
        <OverlayPortal portal={BaseMenu.Portal} kind="menu" container={portalContainer}>
          <BaseMenu.Positioner
            positionMethod="fixed"
            className="ui-navigation-positioner"
            side="right"
            align="start"
            sideOffset={4}
            collisionPadding={12}
          >
            <BaseMenu.Popup className="ui-navigation-popup" data-size={size}>
              <NavigationMenuActions items={item.children} size={size} />
            </BaseMenu.Popup>
          </BaseMenu.Positioner>
        </OverlayPortal>
      </BaseMenu.SubmenuRoot>
    ) : (
      <BaseMenu.Item
        key={item.id}
        className="ui-navigation-action"
        disabled={item.disabled}
        label={item.label}
        data-destructive={item.destructive || undefined}
        onClick={item.onSelect}
      >
        {item.icon ? (
          <span className="ui-navigation-action-icon" aria-hidden="true">
            {item.icon}
          </span>
        ) : null}
        <span>{item.label}</span>
        {item.shortcut ? <kbd className="ui-navigation-shortcut">{item.shortcut}</kbd> : null}
      </BaseMenu.Item>
    ),
  )
}
